def clean_records(records):
    """
    Clean a list of dictionaries by removing deleted records and stripping whitespace from string values.

    Args:
        records (list of dict): A list of dictionaries to clean.

    Returns:
        list of dict: A new list with 'deleted' records removed and all string values stripped of whitespace.
    """
    cleaned = []
    for record in records:
        # Skip records with status 'deleted'
        if record.get('status') == 'deleted':
            continue

        # Create a new dict with whitespace stripped from string values
        cleaned_record = {}
        for key, value in record.items():
            if isinstance(value, str):
                cleaned_record[key] = value.strip()
            else:
                cleaned_record[key] = value

        cleaned.append(cleaned_record)

    return cleaned


