    {'name': '  Bob  ', 'status': 'deleted'},
    {'name': '  Charlie  ', 'status': 'active'}
]
result1 = clean_records(test1)
assert result1 == [
    {'name': 'Alice', 'status': 'active'},
    {'name': 'Charlie', 'status': 'active'}
], f"Test 1 failed: {result1}"

# Test 2: Empty list should return empty list
assert clean_records([]) == [], "Test 2 failed: Empty list should return empty list"

